def first_fit(free_blocks, requests):
    holes = [(start, size) for start, size in free_blocks]
    for need in requests:
        for i in range(len(holes)):
            start, size = holes[i]
            if size >= need:
                holes[i] = (start + need, size - need)
                break
    return [(start, size) for start, size in holes if size > 0]

def best_fit(free_blocks, requests):
    holes = [(start, size) for start, size in free_blocks]
    for need in requests:
        pick = -1
        for i in range(len(holes)):
            start, size = holes[i]
            if size >= need:
                if pick == -1 or size < holes[pick][1]:
                    pick = i
        if pick >= 0:
            start, size = holes[pick]
            holes[pick] = (start + need, size - need)
    return [(start, size) for start, size in holes if size > 0]

def free_total(free_blocks):
    total = 0
    for start, size in free_blocks:
        total += size
    return total

blocks = [(100, 200), (400, 50), (600, 30)]
print(first_fit(blocks, [40, 100]))
